<?php require __DIR__.'/../includes/bootstrap.php'; require_admin(); $id=(int)($_GET['id']??0);$post=['title'=>'','category'=>'news','body'=>'','status'=>'draft','image_path'=>''];if($id){$q=$pdo->prepare('SELECT * FROM posts WHERE id=?');$q->execute([$id]);$post=$q->fetch();if(!$post)exit('Post not found');}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$category=$_POST['category']??'news';$status=$_POST['status']??'draft';$image=$post['image_path'];if(!in_array($category,['news','beneficiary'],true)||!in_array($status,['draft','published'],true))exit('Invalid selection');if(isset($_FILES['image'])&&$_FILES['image']['error']!==UPLOAD_ERR_NO_FILE){$f=$_FILES['image'];$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if($f['error']!==UPLOAD_ERR_OK||!isset($allowed[$mime])||$f['size']>5*1024*1024){$error='Image must be JPG, PNG or WEBP and no larger than 5 MB.';}else{$dir=__DIR__.'/../uploads';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(move_uploaded_file($f['tmp_name'],$dir.'/'.$name))$image='uploads/'.$name;else $error='Could not save image.';}}if(!$title||!$body)$error='Please enter a title and story/update.';if(!$error){if($id){$q=$pdo->prepare("UPDATE posts SET title=?,category=?,body=?,status=?,image_path=?,published_at=IF(?='published',COALESCE(published_at,NOW()),published_at) WHERE id=?");$q->execute([$title,$category,$body,$status,$image,$status,$id]);}else{$q=$pdo->prepare("INSERT INTO posts(title,category,body,status,image_path,published_at) VALUES(?,?,?,?,?,IF(?='published',NOW(),NULL))");$q->execute([$title,$category,$body,$status,$image,$status]);}header('Location: index.php');exit;}} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit post</title><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><p><a href="index.php">← Dashboard</a></p><div class="panel"><h1><?=$id?'Edit post':'Create a post'?></h1><?php if($error):?><p style="color:#a00"><?=e($error)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Title</label><input name="title" maxlength="200" required value="<?=e($_POST['title']??$post['title'])?>"><label>Content</label><textarea name="body" required><?=e($_POST['body']??$post['body'])?></textarea><label>Post type</label><select name="category"><option value="news" <?=($post['category']==='news'?'selected':'')?>>News / announcement</option><option value="beneficiary" <?=($post['category']==='beneficiary'?'selected':'')?>>Beneficiary story</option></select><label>Publication status</label><select name="status"><option value="draft" <?=($post['status']==='draft'?'selected':'')?>>Save as draft</option><option value="published" <?=($post['status']==='published'?'selected':'')?>>Publish</option></select><label>Photo (JPG, PNG or WEBP, max 5 MB)</label><input type="file" name="image" accept="image/jpeg,image/png,image/webp"><?php if($post['image_path']):?><p>Current image: <?=e($post['image_path'])?></p><?php endif;?><button class="btn">Save post</button></form></div></div></body></html>